"use strict";exports.id=6839,exports.ids=[6839],exports.modules={6839:_=>{_.exports=JSON.parse('{"intro_label":"مقدمة","intro_title":"ما هو البيتكوين؟","intro_lead":"البيتكوين (BTC)، الذي ابتكره الشخصية الغامضة ساتوشي ناكاموتو عام 2009، ليس مجرد أول عملة مشفرة — بل هو الشرارة التي أعادت تعريف مفهومَي النقود والثقة. فالبيتكوين ليس مجرد أصل مالي، بل هو بروتوكول برمجي ونظام دفع عالمي يعمل بطريقة لامركزية ومتواصلة. أرسى ظهوره بداية عصر سلسلة الكتل، وهي التقنية التي لا تزال تحوّل القطاعات على نطاق عالمي.","toc_title":"المحتويات","toc_1":"نشأة فكرة ثورية","toc_2":"فلسفة المصدر المفتوح وإرث ناكاموتو","toc_3":"سلسلة الكتل","toc_4":"عملية التحقق والأمان التشفيري","toc_5":"الندرة الرقمية والسيادة النقدية","toc_6":"كيفية تخزين البيتكوين","toc_7":"أين تشتري البيتكوين","toc_8":"كيف يُحدَّد سعر البيتكوين؟","toc_9":"البيتكوين بوصفه أول دين حقيقي في القرن الحادي والعشرين","toc_10":"المصادر والموارد","s1_title":"نشأة فكرة ثورية لامركزية","s1_p1_a":"وُلد البيتكوين في أعقاب الأزمة المالية العالمية عام 2008. في أكتوبر من ذلك العام، نشر شخص — أو ربما مجموعة — يستخدم اسم ساتوشي ناكاموتو المستعار وثيقةً من تسع صفحات بعنوان","s1_p1_em":"البيتكوين: نظام نقد إلكتروني من نظير إلى نظير","s1_p1_b":"اقترحت هذه الورقة نظاماً للمعاملات الإلكترونية لا يستلزم الثقة بأي طرف ثالث: لا بنوك، ولا حكومات، ولا وسطاء من أي نوع.","s1_p2":"في الثالث من يناير 2009، أحيت شبكة البيتكوين بتعدين أول كتلة — كتلة النشأة. كان محفوراً في تلك الكتلة رسالة: \xabصحيفة التايمز، 3 يناير 2009، وزير المالية على شفا عملية إنقاذ ثانية للبنوك.\xbb طابع زمني للعالم الذي وُلد فيه البيتكوين. إعلان هادئ عن النوايا.","s1_p3":"لم تكن الفكرة بالكامل جديدة. فقد ظل علماء التشفير والمدافعون عن الخصوصية الرقمية يعملون على مفاهيم النقد الرقمي لعقود. ما جعل البيتكوين مختلفاً هو الحل الأنيق الذي قدّمه لـ\xabمشكلة الإنفاق المزدوج\xbb — وهي تحدي منع أي شخص من إنفاق نفس المال الرقمي مرتين دون الاعتماد على جهة موثوقة للمتابعة. حلّ البيتكوين هذه المعضلة بالرياضيات والإجماع، لا بالبنوك.","s2_title":"فلسفة المصدر المفتوح وإرث ناكاموتو","s2_p1":"البيتكوين برنامج مفتوح المصدر. شفرته البرمجية متاحة للعموم ليقرأها أي أحد في العالم أو يراجعها أو ينسخها أو يحسّنها. لم يكن هذا مجرد قرار تقني — بل كان قراراً فلسفياً. كان بإمكان ناكاموتو أن يُبقي الشفرة سرية ويبني شركة حولها. بدلاً من ذلك، منحها للعالم مجاناً.","s2_p2":"يعني المصدر المفتوح أن لا شركة واحدة تمتلك البيتكوين. لا يوجد رئيس تنفيذي، ولا مقر رئيسي، ولا خط لخدمة العملاء. يُنسَّق التطوير طوعاً من قِبل مساهمين حول العالم. لا يمكن إجراء تغييرات على البروتوكول إلا إذا وافقت عليها الشبكة الأوسع — حماية مضمّنة ضد التلاعب من أي طرف منفرد.","s2_p3":"يُعتقد أن ناكاموتو عدّن نحو مليون وحدة BTC في الأيام الأولى للبيتكوين. ولم تتحرك أي من تلك العملات قط. سواء كان ناكاموتو قد توفي، أو يعيش متنكراً، أو يختار ببساطة عدم البيع، تظل تلك العملات محتفظاً بها حتى اليوم. بالنسبة لكثيرين في المجتمع، هذه أقوى إشارة على الإطلاق: مهما كان ناكاموتو، لم يكن الأمر قط يتعلق بالإثراء الشخصي.","s2_p4":"حوالي عام 2011، انسحب ناكاموتو تدريجياً من جميع الاتصالات، وسلّم الوصاية على المشروع لمجتمع المطورين قبل أن يختفي تماماً. وقد زاد هذا الغياب من عمق الإرث. لا يحتاج البيتكوين إلى مبتكره لكي يستمر — وربما كان ذلك هو المقصود.","s3_title":"سلسلة الكتل","s3_p1":"سلسلة الكتل هي سجل رقمي موزع — سجل للمعاملات لا يُخزَّن في مكان واحد، بل في آلاف الحواسيب حول العالم في آنٍ واحد. كل حاسوب يحتفظ بنسخة يُسمى عقدة. لا توجد عقدة واحدة مسؤولة عن التحكم. كلها تحتفظ بنفس المعلومات وتتحقق من بعضها البعض.","s3_p2":"يُنظَّم السجل في كتل. تحتوي كل كتلة على دفعة من المعاملات الأخيرة، وطابع زمني، و— الأهم — بصمة رقمية فريدة (تُسمى الهاش) للكتلة التي سبقتها. هذا ما ينشئ السلسلة: كل كتلة مرتبطة رياضياً بسابقتها. لو حاولت تعديل معاملة في كتلة قديمة، لتغيّر هاشها، وكُسر الرابط مع كل كتلة لحقتها. سترفض الشبكة ذلك فوراً.","s3_p3":"هذا الهيكل يجعل سلسلة كتل البيتكوين محصّنة فعلياً ضد التلاعب. لإعادة كتابة التاريخ، يحتاج المهاجم إلى إعادة عمل الحسابات الكاملة لكل كتلة لاحقة، وبسرعة تفوق مجمل بقية الشبكة — وهو أمر استثنائي ومستحيل من الناحية العملية.","s3_p4":"سلسلة الكتل أيضاً شفافة تماماً. كل معاملة جرت على البيتكوين علنية ومرئية بصفة دائمة لأي أحد. لا توجد تحويلات مخفية، ولا حسابات سرية. تأتي الخصوصية ليس من السرية بل من الكنية: العناوين هي سلاسل من الحروف والأرقام، وليست أسماء.","s4_title":"عملية التحقق والأمان التشفيري","s4_p1":"حين ترسل بيتكوين، تُبثّ معاملتك إلى الشبكة كلها. تستقبلها آلاف العقد وتتحقق من صحتها — أنك تمتلك فعلاً الأموال التي تحاول إرسالها، وأن توقيعك الرقمي أصيل. لكن قبل أن تُسجَّل بصفة دائمة في سلسلة الكتل، يجب أن تُدرَج في كتلة. هنا يأتي دور المعدِّنين.","s4_p2":"التعدين هو عملية تجميع المعاملات المعلّقة في كتلة جديدة وإضافتها إلى السلسلة. لذلك يجب على المعدِّنين حل لغز رياضي: إيجاد رقم (يُسمى الـnonce) يُنتج حين يجمع مع بيانات الكتلة هاشاً ذا تنسيق محدد جداً. لا توجد اختصارات — يجب أن يجرب المعدّنون مليارات التوليفات في الثانية حتى تنجح إحداها. يُسمى هذا إثبات العمل.","s4_p3":"أول معدّن يجد الحل يضيف الكتلة ويكسب مكافأة من بيتكوين مخلوق حديثاً، إضافة إلى رسوم المعاملات المدرجة في تلك الكتلة. هذه هي الطريقة الوحيدة لدخول البيتكوين الجديد إلى التداول. تُعدَّل صعوبة اللغز تلقائياً كل أسبوعين بحيث تُكتشف الكتل كل عشر دقائق تقريباً بصرف النظر عن قدر القوة الحاسوبية في الشبكة.","s4_p4":"لدالة الهاش التشفيرية في قلب هذه العملية خاصية رائعة: أي تغيير في المدخلات — حتى حرف واحد — يُنتج مخرجاً مختلفاً كلياً. هذا يعني أنه بمجرد قبول الكتلة من الشبكة، تُختم محتوياتها. تعديل أي معاملة سابقة سيستلزم إعادة كل العمل الحسابي منذ تلك النقطة، بينما يواصل بقية معدّني العالم البناء فوق السلسلة الأمينة.","s5_title":"الندرة الرقمية والسيادة النقدية","s5_p1":"لن يوجد سوى 21 مليون بيتكوين على الإطلاق. هذه ليست سياسة شركة أو لائحة حكومية — بل مكتوبة مباشرةً في البروتوكول، ويُطبَّقها إجماع كل عقدة في الشبكة. لا يستطيع أي سلطة زيادة العرض. لا يمكن لأي طارئ أن يبرر طباعة المزيد. السقف مطلق.","s5_p2":"تُهندَس هذه الندرة من خلال التنصيف: كل أربع سنوات تقريباً، تُخفَّض مكافأة المعدّنين عن كل كتلة جديدة إلى النصف. بدأ البيتكوين بمكافأة 50 BTC للكتلة. اعتباراً من 2024 أصبحت 3.125 BTC. تستمر هذه العملية حتى تقترب المكافأة من الصفر — عندها سيُعال المعدّنون كلياً من رسوم المعاملات. يُتوقع تعدين آخر بيتكوين حوالي عام 2140.","s5_p3":"يتناقض هذا العرض المتناقص المتوقع تناقضاً حاداً مع العملات التقليدية، حيث يمكن للبنوك المركزية توسيع عرض النقود في أي وقت. التضخم — الاضمحلال الصامت للقوة الشرائية — سمة متعمدة في النظم النقدية للعملات الورقية. البيتكوين، بتصميمه، لا يمكن أن يتضخم. لا يمكن مصادرته بمرسوم. يوجد خارج سيطرة أي حكومة أو مؤسسة أو شخص منفرد.","s5_p4":"بهذا المعنى، يمثل البيتكوين شكلاً جديداً من السيادة النقدية — قدرة أي فرد في أي مكان في العالم على حيازة القيمة ونقلها دون استئذان أحد.","s6_title":"كيفية تخزين البيتكوين","s6_p1":"\xabليس مفتاحك، ليس عملتك.\xbb هذا هو المبدأ الأول لحضانة البيتكوين، ومن الجدير فهمه قبل أن تشتري ساتوشياً واحداً.","s6_p2":"حين تشتري بيتكوين في منصة تداول وتتركه هناك، فأنت لا تمتلك البيتكوين حقاً. أنت تمتلك وعداً من تلك المنصة بأن تردّه إليك. يمكن للمنصات أن تُخترق أو تُفلس أو تُجمّد السحوبات. حدث هذا مرات عديدة. الملكية الحقيقية تعني التحكم في مفاتيحك الخاصة — أوراق الاعتماد التشفيرية التي تثبت حقك في إنفاق كمية معينة من البيتكوين.","s6_p3":"المحافظ هي الأدوات التي تدير هذه المفاتيح. وتأتي في عدة أشكال، كل منها يقدم موازنة بين الراحة والأمان:","s6_hot_title":"المحافظ الساخنة","s6_hot_text":"برامج متصلة بالإنترنت. تطبيقات الهاتف مثل BlueWallet أو Blockstream Green مريحة للمبالغ الصغيرة والاستخدام اليومي، لكنها تنطوي على مخاطر أعلى بسبب التعرض للإنترنت.","s6_desktop_title":"محافظ سطح المكتب","s6_desktop_text":"برامج مثل Sparrow Wallet أو Electrum تعمل على حاسوبك. تمنح مزيداً من التحكم والميزات، وتناسب المستخدمين المتوسطين.","s6_hw_title":"محافظ الأجهزة","s6_hw_text":"أجهزة مادية مثل Ledger وTrezor وColdcard تحفظ مفاتيحك الخاصة في وضع غير متصل بالإنترنت على رقاقة مخصصة. الخيار الأكثر أماناً للمبالغ الكبيرة، والنهج الموصى به للتخزين طويل الأمد.","s6_p4":"كل محفظة تولّد عبارة استرداد: قائمة من 12 أو 24 كلمة عادية تُشكّل النسخة الاحتياطية الرئيسية لمحفظتك. من يملك هذه العبارة يستطيع الوصول إلى أموالك. دوّنها على ورقة، احفظها في مكان آمن وغير متصل بالإنترنت، ولا تشاركها مع أحد أبداً. فقدان عبارة الاسترداد يعني فقدان بيتكوينك بصفة دائمة. لا توجد خدمة عملاء للاتصال بها.","s7_title":"أين تشتري البيتكوين","s7_p1":"يُباع البيتكوين ويُشترى في منصات التداول — منصات تُطابق بين المشترين والبائعين وتُنجز المعاملة. الإجراء مباشر: سجّل حساباً، تحقق من هويتك (تطلب معظم المنصات المنظّمة ذلك)، أودع مالاً، واشترِ بيتكوين بسعر السوق الحالي.","s7_p2":"النوع الأكثر شيوعاً هو المنصات المركزية (CEX): منصات مثل Coinbase وKraken وMEXC. هذه المنصات سهلة الاستخدام وتتولى التعقيد التقني نيابةً عنك. حين تشتري في منصة مركزية، تحتفظ المنصة بالبيتكوين في عهدتها — مشابهة لكيفية احتفاظ البنك بأموالك — حتى تقرر سحبه إلى محفظتك.","s7_p3":"عند اختيار منصة، ضع في الاعتبار ما يلي:","s7_li_reg_title":"الترخيص والسمعة","s7_li_reg_text":"هل المنصة مرخصة في بلدك؟ منذ متى وهي تعمل؟","s7_li_sec_title":"السجل الأمني","s7_li_sec_text":"هل تعرضت للاختراق من قبل؟ كيف تحمي أموال المستخدمين؟","s7_li_fees_title":"الرسوم","s7_li_fees_text":"تتباين رسوم التداول ورسوم السحب وتكاليف تحويل العملات تبايناً كبيراً بين المنصات.","s7_li_wd_title":"سهولة السحب","s7_li_wd_text":"يجب أن تستطيع سحب بيتكوينك إلى محفظتك الخاصة في أي وقت.","s7_p4":"القاعدة الذهبية بعد الشراء: اسحب إلى محفظتك. المنصات ليست للتخزين طويل الأمد. إنها مكان لتحويل المال إلى بيتكوين — ليس مكاناً للاحتفاظ به.","s8_title":"كيف يُحدَّد سعر البيتكوين؟","s8_p1":"لا توجد سلطة مركزية تُحدد سعر البيتكوين. لا يوجد مجلس إدارة، ولا هيئة حكومية، ولا خوارزمية تقرر قيمة البيتكوين الواحد. ينشأ السعر كلياً من تفاعل المشترين والبائعين عبر آلاف المنصات حول العالم. حين يريد المشترون المزيد من البائعين، يرتفع السعر. وحين يريد البائعون المزيد من المشترين، ينخفض.","s8_p2":"تؤثر عوامل عديدة في هذا التوازن: الظروف الاقتصادية الكلية (التضخم وأسعار الفائدة وأزمات العملات)، والتطورات التنظيمية، والترقيات التقنية، واعتماد المؤسسات، والتغطية الإعلامية، وكذلك مشاعر السوق الأشمل. لا يعيش البيتكوين في فراغ — بل يتفاعل مع العالم من حوله، وكثيراً ما يُضخَّم هذا التفاعل.","s8_p3":"يؤدي العرض الثابت دوراً جوهرياً في ديناميكيات الأسعار على المدى الطويل. مع 21 مليون عملة فقط — يُقدَّر أن ملايين منها قد فُقدت إلى الأبد — يُشكّل تنامي الطلب في مواجهة عرض محدود بصفة دائمة قوة اقتصادية هائلة. لكن تحركات الأسعار على المدى القصير تتأثر بالمضاربة والرافعة المالية والعاطفة الإنسانية بقدر ما تتأثر بأي تحليل للأسس.","s8_p4_a":"البيتكوين شديد التقلب. تراجعات بنسبة 50% أو أكثر في دورة واحدة ليست استثنائية. بالنسبة للمستثمرين طويلي الأمد، هذا هو ثمن الدخول — وتاريخياً كان المكافأة على الصبر كبيرة. لهذا السبب يصبح فهم الاستراتيجية بالغ الأهمية بقدر فهم الأصل ذاته. انظر","s8_p4_link":"استراتيجيات الاستثمار","s8_p4_b":"للاطلاع على دليل عملي.","s9_title":"البيتكوين بوصفه أول دين حقيقي في القرن الحادي والعشرين","s9_p1":"كل دين يولد من جرح. إدراك بأن شيئاً ما في العالم معطوب معطوباً جوهرياً — وإيمان بأن ثمة طريقاً نحو ما هو أفضل. البيتكوين ليس استثناء. جرحه التأسيسي هو طباعة النقود: انحطاط العملة الهادئ المتواصل الذي يتحمله الناس العاديون الذين يعملون طوال حياتهم لتجميع المدخرات. كل وحدة عملة تُطبع دون غطاء هي نقل للثروة من المدخرين إلى أولئك الذين يتحكمون في المطبعة. إنه شكل من السرقة يجعله الغموض غير مرئي. يُسميه أصحاب البيتكوين بما هو عليه: انحلال. وقد كرّسوا أنفسهم لوضع حد له.","s9_p2_bold":"خطيئة المركزية.","s9_p2_text":"على مر التاريخ، أساءت كل مؤسسة مُنحت سلطة التحكم في النقود استخدامها في نهاية المطاف. ليس لأن المسؤولين أشرار دائماً — بل لأن السلطة المركزية تجذب الفساد كما يجذب الضوء الفراشات. إنه أمر هيكلي، حتمي. حين تتحكم جهة واحدة في السجل، يخدم السجل تلك الجهة في نهاية المطاف. يُزيل البيتكوين هذا الاحتمال كلياً. لا يوجد متحكم في السجل. لا يوجد من يمكن إفساده. الكود هو القانون — لا يتغير، شفاف، ولا مبالٍ بالسلطة.","s9_p3_bold":"ميثاق المساواة.","s9_p3_text":"في شبكة البيتكوين، الجميع متساوون. معاملتك تتبع القواعد ذاتها سواء كنت مليارديراً أو طالباً معه عشرة يوروهات. لا يمكن حظر أحد من الإرسال أو الاستقبال. لا يمكن لأحد أن يُبعَد عن المنصة أو يُجمَّد حسابه أو يخضع لرسوم مختلفة بسبب هويته أو مكان إقامته. البروتوكول لا يُميّز. هذا ليس مجرد خاصية تقنية — إنه خاصية أخلاقية. يتحد أصحاب البيتكوين بالإيمان بأن نظاماً مالياً أكثر عدلاً ممكن، وأن الكود الذي يشغّلونه كل يوم هو أقرب ما وصلت إليه الإنسانية لبنائه.","s9_p4_bold":"وعد فرط البيتكونة.","s9_p4_text":"في قلب رؤية البيتكوين نبوءة: أنه في يوم ما سيغدو البيتكوين المعيار العالمي للقيمة. ليس أصلاً للمضاربة. ليس تقنية متخصصة. بل أساس نظام نقدي جديد. هذا المستقبل — المُسمى بفرط البيتكونة — سيعني نهاية طباعة النقود، ونهاية انحطاط العملة، وبداية حقبة تضطر فيها الحكومات إلى كسب أموال مواطنيها بدلاً من إنشاء المزيد منها ببساطة. إنه رؤية خلاصية — أرض موعودة — تدفع أصحاب البيتكوين عبر كل انهيار، وكل هجوم تنظيمي، وكل موجة سخرية من التيار السائد.","s9_p5":"تسميته ديناً أو لا يبقى مسألة تعريف. ما لا جدال فيه هو عمق الإيمان، وتماسك الرؤية، وحجم المجتمع الذي نظّم نفسه حولها. البيتكوين ليس مجرد رهان على تقنية. إنه تصريح بالكيفية التي ينبغي أن يعمل بها العالم — والتزام ببنائه.","sources_label":"مزيد من القراءة","sources_title":"المصادر والموارد","sources_intro":"البيتكوين نفق أرنب لا قرار له. كلما تعلمت أكثر، غصت أعمق. الموارد التالية نقطة انطلاق جيدة — بعضها تقني، وبعضها في متناول الجميع، وكلها تستحق وقتك.","sources_wp_desc":"الوثيقة الأصلية المكونة من تسع صفحات التي كتبها ساتوشي ناكاموتو وأشعلت كل شيء. قراءة إلزامية.","sources_learnme_desc":"أحد أوضح الموارد التعليمية المتاحة. يغطي كل شيء من أدلة المبتدئين إلى التعمق التقني، مع مستكشف تفاعلي لسلسلة الكتل.","sources_wiki_desc":"نظرة عامة واسعة وموثقة جيداً على تاريخ البيتكوين وتقنيته وتلقّيه.","sources_bw_desc":"دليل عملي للحضانة الذاتية وأنواع المحافظ وأمان عبارة الاسترداد.","sources_btalk_desc":"منتدى البيتكوين الأصلي الذي أسسه ساتوشي ناكاموتو. لا تزال أقدم النقاشات حول البيتكوين محفوظة هناك."}')}};